-- Deterministic local-only users. Password for every demo account: DemoPass123!
-- These auth rows mirror GoTrue's local SQL seed pattern; never use these credentials in production.
update public.profiles set role='admin' where id='30000000-0000-0000-0000-000000000001';
on conflict (seller_id) do update set completed_sales=excluded.completed_sales,review_count=excluded.review_count,average_rating=excluded.average_rating,dispute_count=excluded.dispute_count,updated_at=now();
